use std :: process :: Command ; use std :: fs ; use std :: path :: Path ; use std :: time :: Instant ; fn test_performance_recording () -> ZkperfTestResult { let start = Instant :: now () ; let test_name = "Performance Recording" ; let perf_dir = "./zkperf_perf_output" ; if Path :: new (perf_dir) . exists () { let _ = std :: fs :: remove_dir_all (perf_dir) ; } match Command :: new ("cargo") . args (& ["run" , "--bin" , "zkperf-record" , "--" , "run" , "./simple_repository_mathematical_atlas" , perf_dir]) . current_dir ("./zkperf") . output () { Ok (output) => { if output . status . success () { let perf_files = vec ! [format ! ("{}/summary.cbor" , perf_dir) , format ! ("{}/trace.cbor" , perf_dir) ,] ; let mut perf_generated = false ; for file_path in perf_files { if Path :: new (& file_path) . exists () { perf_generated = true ; break ; } } if perf_generated { ZkperfTestResult :: new (test_name . to_string () , true , start . elapsed () . as_millis () as u64 , None , Some ("Performance data generated successfully" . to_string ()) , None ,) } else { ZkperfTestResult :: new (test_name . to_string () , false , start . elapsed () . as_millis () as u64 , None , None , Some ("No performance data files found" . to_string ()) ,) } } else { ZkperfTestResult :: new (test_name . to_string () , false , start . elapsed () . as_millis () as u64 , None , None , Some (format ! ("ZKperf recording failed: {}" , String :: from_utf8_lossy (& output . stderr))) ,) } } Err (e) => { ZkperfTestResult :: new (test_name . to_string () , false , start . elapsed () . as_millis () as u64 , None , None , Some (format ! ("Failed to execute ZKperf: {}" , e)) ,) } } }